var blue = '#aeb7dc';
var blueEdge = '#8392b2';
var orange = '#f0a078';
var axis = '#111';
var mutedAxis = '#333';

var defs = draw.defs();
var grad = defs.gradient('linear', function(add) {
  add.stop(0, '#ffffff', 0.76);
  add.stop(0.45, '#cbd0e8', 0.70);
  add.stop(1, '#8f9ccc', 0.62);
