var leftAll = draw.group();
var rightAll = draw.group();
var labels = draw.group();
var dynamic = draw.group();
var callouts = draw.group();

var LC = { x: 170, y: 178, R: 137 };
var RC = { x: 555, y: 178, rx: 138, ry: 54 };

function labelText(parent, txt, x, y, size, anchor) {
  return parent.text(txt).font({
    family: 'serif',
    size: size || 17,
    style: 'italic',
    anchor: anchor || 'middle'
  }).center(x, y).attr({
    'paint-order': 'stroke',
    stroke: '#fff',
