  rightAll.clear();

  leftAll.circle(LC.R * 2).center(LC.x, LC.y).fill(grad).stroke({ color: blueEdge, width: 1.4 });
  arrow(leftAll, LC.x, LC.y + LC.R + 28, LC.x, LC.y - LC.R - 27, axis, 1.35);
