// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 706, H = 306;
draw.viewbox(0, 0, W, H);

var state = { ringRadius: 0.55, annulusWidth: 0.06, perspective: false, step: 0, touched: false };

var axis = '#111111';
var diskEdge = '#8492ad';
var orange = '#efa077';

var defs = draw.defs();
var grad = defs.gradient('linear', function(add) {
  add.stop(0, '#ffffff', 0.86);
  add.stop(0.48, '#cfd4ea', 0.76);
  add.stop(1, '#9aa7d1', 0.70);
}).from(0, 0).to(1, 0);

var leftScene = draw.group();
var rightScene = draw.group();
var formulaScene = draw.group();

var LC = { x: 150, y: 153, R: 132 };
var RC = { x: 514, y: 156, rx: 132, ry: 53 };

function strokedText(parent, txt, x, y, size, anchor, italic) {
  return parent.text(txt).font({
    family: 'serif',
    size: size || 17,
    anchor: anchor || 'middle',
    style: italic === false ? 'normal' : 'italic'
  }).center(x, y).fill(axis).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
}

function arrow(parent, x1, y1, x2, y2, color, width, both) {
  color = color || axis;
  width = width || 1.25;
  var g = parent.group();
  g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  function head(ax, ay, bx, by) {
    var ang = Math.atan2(by - ay, bx - ax);
    var len = 8.2, wid = 4.7;
    var p1 = [bx, by];
    var p2 = [bx - len * Math.cos(ang) + wid * Math.sin(ang), by - len * Math.sin(ang) - wid * Math.cos(ang)];
    var p3 = [bx - len * Math.cos(ang) - wid * Math.sin(ang), by - len * Math.sin(ang) + wid * Math.cos(ang)];
    g.polygon([p1, p2, p3].map(function(p){ return p.join(','); }).join(' ')).fill(color).stroke('none');
  }
  head(x1, y1, x2, y2);
  if (both) head(x2, y2, x1, y1);
  return g;
}

function radialPoint(cx, cy, r, deg) {
  var a = deg * Math.PI / 180;
  return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
}

function ellipsePoint(cx, cy, rx, ry, deg) {
  var a = deg * Math.PI / 180;
  return { x: cx + rx * Math.cos(a), y: cy + ry * Math.sin(a) };
}

function curvedArrow(parent, d, tipX, tipY, prevX, prevY, color) {
  var g = parent.group();
  g.path(d).fill('none').stroke({ color: color || axis, width: 1.9, linecap: 'round' });
  var ang = Math.atan2(tipY - prevY, tipX - prevX);
  var len = 8.5, wid = 4.8;
  var p1 = [tipX, tipY];
  var p2 = [tipX - len * Math.cos(ang) + wid * Math.sin(ang), tipY - len * Math.sin(ang) - wid * Math.cos(ang)];
  var p3 = [tipX - len * Math.cos(ang) - wid * Math.sin(ang), tipY - len * Math.sin(ang) + wid * Math.cos(ang)];
  g.polygon([p1, p2, p3].map(function(p){ return p.join(','); }).join(' ')).fill(color || axis).stroke('none');
  return g;
}

function syncControls() {
  var maxR = Math.max(0.05, 1 - state.annulusWidth / 2);
  if (state.ringRadius > maxR) state.ringRadius = maxR;
  document.getElementById('ringRadiusInput').value = state.ringRadius.toFixed(2);
  document.getElementById('ringRadiusVal').value = state.ringRadius.toFixed(2);
  document.getElementById('annulusWidthInput').value = state.annulusWidth.toFixed(2);
  document.getElementById('annulusWidthVal').value = state.annulusWidth.toFixed(2);
  document.getElementById('viewEmphasisInput').checked = !!state.perspective;
  document.getElementById('viewEmphasisVal').value = state.perspective ? 'Perspective disk' : 'Face-on disk';
}

function drawLeftScene(rEff, dr) {
  leftScene.clear();

  leftScene.circle(LC.R * 2).center(LC.x, LC.y)
    .fill(grad).stroke({ color: diskEdge, width: 1.25 });

  var ringRadius = rEff * LC.R;
  var ringWidth = Math.max(2.6, dr * LC.R);
  var ring = leftScene.circle(ringRadius * 2).center(LC.x, LC.y)
    .fill('none')
    .stroke({ color: orange, width: ringWidth, opacity: 0.78, linecap: 'round' });

  arrow(leftScene, LC.x, LC.y + LC.R + 32, LC.x, LC.y - LC.R - 21, axis, 1.15);
  arrow(leftScene, LC.x - LC.R - 30, LC.y, LC.x + LC.R + 25, LC.y, axis, 1.15);
  strokedText(leftScene, 'x', LC.x - 11, LC.y - LC.R - 20, 16);
  strokedText(leftScene, 'y', LC.x + LC.R + 17, LC.y + 10, 16);
  strokedText(leftScene, 'z', LC.x - 8, LC.y - 9, 16, 'middle', false);

  arrow(leftScene, LC.x, LC.y, LC.x - 94, LC.y + 94, axis, 1.15);
  strokedText(leftScene, 'R', LC.x - 54, LC.y + 37, 18, 'middle', true);

  var rp = radialPoint(LC.x, LC.y, ringRadius, 48);
  arrow(leftScene, LC.x, LC.y, rp.x, rp.y, axis, 1.15);
  strokedText(leftScene, 'r', LC.x + 31, LC.y + 24, 17);

  var deg = -25;
  var a = deg * Math.PI / 180;
  var mid = radialPoint(LC.x, LC.y, ringRadius, deg);
  var half = ringWidth * 0.55;
  var pIn = { x: mid.x - half * Math.cos(a), y: mid.y - half * Math.sin(a) };
  var pOut = { x: mid.x + half * Math.cos(a), y: mid.y + half * Math.sin(a) };
  arrow(leftScene, pIn.x, pIn.y, pOut.x, pOut.y, axis, 1.05, true);
  strokedText(leftScene, 'dr', pOut.x + 21, pOut.y + 4, 17);

  ring.on('mousemove', function(e) {
    showTooltip('The highlighted annulus is one thin ring of mass dm at radius r.', e);
  }).on('mouseleave', hideTooltip).on('click', function() {
    showPopup('Annular mass element', 'The disk is decomposed into thin concentric rings. Each orange ring is treated as mass dm located approximately the same distance r from the rotation axis.');
  }).css('cursor', 'pointer');
}

function drawRightScene(rEff, dr) {
  rightScene.clear();

  rightScene.ellipse(RC.rx * 2, RC.ry * 2).center(RC.x, RC.y)
    .fill(grad).stroke({ color: diskEdge, width: 1.25 });

  var rx = rEff * RC.rx;
  var ry = rEff * RC.ry;
  var ringWidth = Math.max(2.4, dr * RC.rx * 0.68);

  var ring = rightScene.ellipse(rx * 2, ry * 2).center(RC.x, RC.y)
    .fill('none')
    .stroke({ color: orange, width: ringWidth, opacity: 0.88, linecap: 'round' });

  arrow(rightScene, RC.x, RC.y + 88, RC.x, RC.y - 129, axis, 1.1);
  arrow(rightScene, RC.x - 150, RC.y, RC.x + 161, RC.y, axis, 1.1);
  arrow(rightScene, RC.x + 58, RC.y - 55, RC.x - 69, RC.y + 76, axis, 1.1);
  strokedText(rightScene, 'z', RC.x - 12, RC.y - 126, 16);
  strokedText(rightScene, 'y', RC.x + 154, RC.y + 10, 16);
  strokedText(rightScene, 'x', RC.x - 64, RC.y + 76, 16);

  curvedArrow(rightScene, 'M 472 76 C 443 72 444 59 482 57 C 520 55 548 60 558 70', 558, 70, 547, 63, axis);

  var erp = ellipsePoint(RC.x, RC.y, rx, ry, -29);
  arrow(rightScene, RC.x, RC.y, erp.x, erp.y, axis, 1.15);
  strokedText(rightScene, 'r', (RC.x + erp.x) / 2 + 11, (RC.y + erp.y) / 2 + 12, 17);

  var dmP = ellipsePoint(RC.x, RC.y, rx, ry, -29);
  arrow(rightScene, dmP.x + 58, dmP.y - 31, dmP.x + 10, dmP.y - 3, axis, 1.0);
  strokedText(rightScene, 'dm', dmP.x + 72, dmP.y - 35, 18);

  ring.on('mousemove', function(e) {
    showTooltip('This single orange ellipse is the same circular ring viewed in perspective.', e);
  }).on('mouseleave', hideTooltip).on('click', function() {
    showPopup('Same ring, different view', 'The right diagram shows the same full annular ring tilted in perspective. The dm label points to a small piece of that ring, but the mass element represents the whole thin ring.');
  }).css('cursor', 'pointer');
}

function drawFormula(rEff, dr) {
  formulaScene.clear();

  var dmLike = 2 * rEff * dr;
  var contribution = rEff * rEff * dmLike;
  var normalized = Math.max(0, Math.min(1, contribution / 0.40));

  var box = formulaScene.group();
  box.rect(230, 38).radius(6).move(366, 255)
    .fill('#ffffff').opacity(0.90).stroke({ color: '#d8d8d8', width: 1 });

  strokedText(box, 'I = ∫ r² dm', 425, 267, 15, 'middle', false);
  strokedText(box, 'dI = r² dm', 523, 267, 15, 'middle', false);

  box.rect(174, 9).move(394, 280).fill('#eef0f7').stroke({ color: '#b8bfd3', width: 0.8 });
  box.rect(174 * normalized, 9).move(394, 280).fill(orange).opacity(0.95);

  box.on('mousemove', function(e) {
    showTooltip('The bar is proportional to r² dm: it grows with ring mass and grows strongly as r moves outward.', e);
  }).on('mouseleave', hideTooltip).on('click', function() {
    showPopup('Why outer rings matter', 'For a uniform disk, dm is proportional to the area of the thin ring. The rotational-inertia contribution also multiplies that mass by r², so material near the rim counts much more.');
  }).css('cursor', 'pointer');
}

function applyEmphasis() {
  if (state.perspective) {
    leftScene.opacity(0.42);
    rightScene.opacity(1);
  } else {
    leftScene.opacity(1);
    rightScene.opacity(0.62);
  }
  formulaScene.opacity(1);
}

function render() {
  var dr = state.annulusWidth;
  var rEff = Math.min(state.ringRadius, 1 - dr / 2);
  state.ringRadius = Math.max(0.05, rEff);

  drawLeftScene(state.ringRadius, dr);
  drawRightScene(state.ringRadius, dr);
  drawFormula(state.ringRadius, dr);
  applyEmphasis();
}

function update_ringRadius(v) {
  state.touched = true;
  state.ringRadius = +v;
  syncControls();
  render();
}

function update_annulusWidth(v) {
  state.touched = true;
  state.annulusWidth = +v;
  syncControls();
  render();
}

function toggle_viewEmphasis(on) {
  state.touched = true;
  state.perspective = !!on;
  syncControls();
  render();
}

var demoSteps = [
  {
    title: 'Identify the ring element',
    narration: 'The orange strip is not a small patch: it is a full annular ring at radius r from the z-axis. This ring is the mass element dm used in the moment-of-inertia integral.',
    state: { ringRadius: 0.55, annulusWidth: 0.06, viewEmphasis: 'Face-on disk' }
  },
  {
    title: 'Move the same mass farther out',
    narration: 'Drag the radius outward and watch the same type of ring move toward the rim. The contribution indicator grows rapidly because the integrand contains r² dm, not just dm.',
    state: { ringRadius: 0.85, annulusWidth: 0.06, viewEmphasis: 'Face-on disk' }
  },
  {
    title: 'Change the amount of mass in the ring',
    narration: 'Widening dr makes the annular strip cover more area, so dm increases. The ring still represents material all at approximately the same radius r when dr is small.',
    state: { ringRadius: 0.65, annulusWidth: 0.14, viewEmphasis: 'Face-on disk' }
  },
  {
    title: 'Connect the two views',
    narration: 'Switch to the perspective view: the orange ellipse is the same ring, now seen as a tilted disk rotating about the z-axis. The dm label marks one piece of that full circular ring.',
    state: { ringRadius: 0.65, annulusWidth: 0.06, viewEmphasis: 'Perspective disk' }
  }
];

function applyStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var s = demoSteps[state.step].state;
  state.ringRadius = s.ringRadius;
  state.annulusWidth = s.annulusWidth;
  state.perspective = s.viewEmphasis === 'Perspective disk';
  state.touched = state.step > 0;

  syncControls();
  document.getElementById('demoNarration').textContent = demoSteps[state.step].narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/4: ' + demoSteps[state.step].title;
